Small inventory service fixture. No network or dependencies are required.

--- package.json ---
{"type":"module","private":true}

--- src/channels/audit.js ---
export function handle(value) { return `audit:${JSON.stringify(value)}`; }

--- src/channels/legacy.js ---
export function handle(value) { return `legacy:${value}`; }

--- src/channels/mail.js ---
import { encode } from '../codec.js';
export function handle(value) { return `mail:${encode(value)}`; }

--- src/codec.js ---
export function encode(value) { return String(value).trim().toLowerCase(); }

--- src/dispatch.js ---
import { registry } from './registry.js';
export function dispatch(event) {
  const handler = registry[event.kind];
  if (!handler) throw new Error('unknown kind');
  return handler(event.payload);
}

--- src/preview.js ---
import { handle } from './channels/legacy.js';
export function preview(value) { return handle(value); }

--- src/registry.js ---
import { handle as mail } from './channels/mail.js';
import { handle as audit } from './channels/audit.js';
export const registry = Object.assign(Object.create(null), { mail, audit });

command:
cat > answer.json <<'EOF'
{
  "registered_files": [
    "src/channels/audit.js",
    "src/channels/mail.js"
  ],
  "selected_file": "src/channels/mail.js",
  "selected_output": "mail:hi",
  "unknown_kind_error": "unknown kind",
  "target_depends_on_runtime_kind": true,
  "legacy_reachable_from_dispatch": false
}
EOF
node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { dispatch } from './src/dispatch.js';
import { registry } from './src/registry.js';
import { handle as audit } from './src/channels/audit.js';
import { handle as mail } from './src/channels/mail.js';
import { handle as legacy } from './src/channels/legacy.js';

const answer = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer), [
  'registered_files', 'selected_file', 'selected_output', 'unknown_kind_error',
  'target_depends_on_runtime_kind', 'legacy_reachable_from_dispatch'
]);
assert.deepEqual(answer.registered_files, ['src/channels/audit.js', 'src/channels/mail.js']);
assert.deepEqual(Object.keys(registry).sort(), ['audit', 'mail']);
assert.equal(registry.audit, audit);
assert.equal(registry.mail, mail);
assert.equal(Object.values(registry).includes(legacy), answer.legacy_reachable_from_dispatch);
assert.equal(answer.selected_file, 'src/channels/mail.js');
assert.equal(dispatch({kind: 'mail', payload: ' Hi '}), answer.selected_output);
assert.equal(dispatch({kind: 'audit', payload: ' Hi '}), 'audit:" Hi "');
assert.throws(() => dispatch({kind: 'missing', payload: ' Hi '}), error => error.message === answer.unknown_kind_error);
assert.equal(answer.target_depends_on_runtime_kind, true);
console.log('answer.json schema and dispatch checks passed');
EOF

